class PublisherSpec extends AnyFunSuite with Listener {   // suite is the collaborator
  private val seen = mutable.Buffer.empty[String]
  override def onEvent(e: String): Unit = seen += e       // record the callback

  test("publishes once") {
    new Publisher(this).change("x")                       // install the suite itself
    assert(seen.toList == List("x"))
  }
}
